def copiar_prazo(apps, schema_editor):
    """O prazo deixa de ser uma data e passa a texto livre (D-34)."""
    Oportunidade = apps.get_model("oportunidades", "Oportunidade")
    for o in Oportunidade.objects.exclude(prazo=None):
        o.prazo_vender = o.prazo.strftime("%d/%m/%Y")
        o.save(update_fields=["prazo_vender"])


